76		@Override
77		public List<NodeDto> queryRuleNodes(RuleNodeQueryParam param) {
78	
79			List<NodeDto> res = new ArrayList<>();
80	
81			// 查询工期节点, 现在这里特殊处理逻辑比较多
82			if (param.getBusinessType() != null && param.getBusinessType().equals(BusinessType.GROUP.getType())
83					&& param.getOrderType() != null && param.getOrderType().equals(SecondType.JINGZHUANG_QUANAN.getSecondType())) {
84				// 团装 & 纯软(原精装全案), 只需要开工交底、安装工程(原竣工验收)
85				res.add(queryGroupSoftScheduleNode());
86			} else if (param.getBusinessType() != null && param.getBusinessType().equals(BusinessType.GROUP.getType())) {
87				// 团装, 没有技术交底 & 软装验收
88				res.add(queryGroupScheduleNode());
89			} else if (param.getOrderType() != null && param.getOrderType().equals(SecondType.JINGZHUANG_QUANAN.getSecondType())) {
90				// 精装全案, 在数据库里有一套节点
91				res.add(queryHardCoverNode());
92			} else if (param.getBusinessType() != null && param.getBusinessType().equals(BusinessType.PARTIAL_DECORATION.getType())) {
93				// 翻新全案, 增加正签 & 待开工交底, 去掉水电验收 & 瓦木验收 & 软装验收
94				res.add(queryPartialScheduleNode());
95			} else {
96				// 普通订单, 查询基础工期节点
97				res.add(queryScheduleNode());
98			}
99	
100			// 竣工前补货节点
101			if (Objects.nonNull(param.getOrderType()) && REPLENISH_SECOND_TYPE_LIST.contains(param.getOrderType())) {
102				NodeDto replenishNode = queryReplenishBeforeCompletionNode();
103				res.add(replenishNode);
104			}
105	
106			// 查询订单节点
107			NodeDto orderNode = queryOrderNode(param);
108			res.add(orderNode);
109			return res;
110		}
