121			if (BusinessVersion.VERSION2_0.getVersion().equals(param.getBusinessVersion())) {
122				// 2.0版本, 只需要基础工期节点
123				scheduleEventNode.setChilds(scheduleEventNode.getChilds().stream()
124						.filter(o -> BASE_SCHEDULE_EVENT.contains(o.getName()))
125						.collect(Collectors.toList()));
126			} else if (param.getBusinessType() != null && param.getBusinessType().equals(BusinessType.GROUP.getType())
127					&& param.getOrderType() != null && param.getOrderType().equals(SecondType.JINGZHUANG_QUANAN.getSecondType())) {
128				// 团装纯软, 只需要开工交底、安装工程(原竣工验收)
129				scheduleEventNode.setChilds(scheduleEventNode.getChilds().stream()
130						.filter(o -> o.getName().equals("开工交底") || o.getName().equals("竣工验收"))
131						.peek(o -> o.setName(o.getName().equals("竣工验收") ? "安装工程" : o.getName()))
132						.collect(Collectors.toList()));
133			} else if (param.getBusinessType() != null && param.getBusinessType().equals(BusinessType.GROUP.getType())) {
134				// 团装, 没有技术交底 & 软装验收
135				scheduleEventNode.setChilds(scheduleEventNode.getChilds().stream()
136						.filter(o -> PARTIAL_DECORATION_EXT_EVENT.contains(o.getName()) || BASE_SCHEDULE_EVENT.contains(o.getName()))
137						.filter(o -> !o.getName().equals("水电验收")
138								&& !o.getName().equals("瓦木验收")
139								&& !o.getName().equals("软装验收"))
140						.collect(Collectors.toList()));
141			} else if (param.getBusinessType() != null && param.getBusinessType().equals(BusinessType.PARTIAL_DECORATION.getType())) {
142				// 翻新全案
143				scheduleEventNode.setChilds(scheduleEventNode.getChilds().stream()
144						.filter(o -> BASE_SCHEDULE_EVENT.contains(o.getName()))
145						.filter(o -> !o.getName().equals("技术交底") && !o.getName().equals("软装验收"))
146						.collect(Collectors.toList()));
147			} else if (param.getOrderType() != null && param.getOrderType().equals(SecondType.JINGZHUANG_QUANAN.getSecondType())) {
148				// 精装全案, 特殊的一套工期节点
149				scheduleEventNode.setName(RuleNodeTypeEnum.HARDCOVER_NODE.getDesc());
150				scheduleEventNode.setChilds(scheduleEventNode.getChilds().stream()
151						.filter(o -> JINGZHUANG_SCHEDULE_EVENT.contains(o.getName()))
152						.collect(Collectors.toList()));
153			} else {
154				// 2.5的普通订单, 和2.0用一套
155				scheduleEventNode.setChilds(scheduleEventNode.getChilds().stream()
156						.filter(o -> BASE_SCHEDULE_EVENT.contains(o.getName()))
157						.collect(Collectors.toList()));
158			}
159			res.add(scheduleEventNode);
160	
161			// 二、竣工前补货节点
162			if (Objects.nonNull(param.getOrderType()) && REPLENISH_SECOND_TYPE_LIST.contains(param.getOrderType())) {
163				NodeDto replenishNode = queryAllReplenishmentEvent(param.getCategoryId());
164				res.add(replenishNode);
165			}
166	
167			// 三、本任务生成节点
168			List<NodeDto> createNodes = queryCreateEvent(param.getCategoryId(), param.getCategoryName(), param.getIndicatorName());
169			if (createNodes != null && !createNodes.isEmpty()) {
170				res.addAll(createNodes);
171			}
172	
173			// 四、查询订单节点(跨品类节点)
174			String categoryId = "";
175			String categoryName = "";
176			if (BusinessVersion.VERSION2_0.getVersion().equals(param.getBusinessVersion())) {
177				categoryId = param.getCategoryId();
178				categoryName = param.getIndicatorName();
179			}
180			List<NodeDto> orderNodes = queryAllOrderEvent(categoryId, categoryName);
181			res.addAll(orderNodes);
182	
183			// code复制为categoryId, 以方便前端搜索
184			for (NodeDto node : res) {
185				node.setCode(node.getCategoryId());
186			}
187	
188			return res;
189		}
