280		private List<NodeDto> queryAllOrderEvent(String categoryId, String categoryName) {
281			// 获取订单事件
282			// 如果传入了categoryId(2.0场景下), 只查询该品类下的事件, 以订单节点命名
283			// 如果没有传入categoryId(2.5场景下), 查询所有品类的事件, 以工品类名命名
284			List<NodeDto> res = new ArrayList<>();
285	
286			IndicatorEventExample example = new IndicatorEventExample();
287			IndicatorEventExample.Criteria criteria = example.createCriteria();
288			criteria.andEventTypeIn(Arrays.asList(
289					EventTypeEnum.TASK_DISPATCH.getValue(),
290					EventTypeEnum.OMS_OFC.getValue(),
291					EventTypeEnum.OMS_OMS.getValue(),
292					EventTypeEnum.CUBE.getValue()));
293			if (StringUtils.isNotBlank(categoryId)) {
294				criteria.andCategoryIdEqualTo(categoryId);
295			}
296			List<IndicatorEvent> scheduleEvent = indicatorEventMapper.selectByExample(example);
297			Map<String, List<IndicatorEvent>> eventMap = scheduleEvent.stream()
298					.filter(o -> !TimeTypeEnum.CREATE_TIME.getValue().equals(o.getTimeType()))
299					.collect(Collectors.groupingBy(IndicatorEvent::getCategoryId));
300			if (StringUtils.isNotBlank(categoryId)) {
301				NodeDto nodeDto = NodeDto.builder()
302						.code("")
303						.name(RuleNodeTypeEnum.ORDER_NODE.getDesc())
304						.categoryId(categoryId)
305						.categoryName(categoryName)
306						.childs(new ArrayList<>())
307						.build();
308				for (IndicatorEvent event : eventMap.getOrDefault(categoryId, Collections.emptyList())) {
309					nodeDto.getChilds().add(NodeDto.builder()
310							.code(event.getCode())
311							.name(event.getEventName())
312							.categoryId(categoryId)
313							.categoryName(categoryName)
314							.childs(null)
315							.build());
316				}
317				res.add(nodeDto);
318			} else {
319				for (Map.Entry<String, List<IndicatorEvent>> entry : eventMap.entrySet()) {
320					String key = entry.getKey();
321					List<IndicatorEvent> events = entry.getValue();
322					NodeDto nodeDto = NodeDto.builder()
323							.code("")
324							.name(events.get(0).getCategoryName())
325							.categoryId(key)
326							.categoryName(events.get(0).getCategoryName())
327							.childs(new ArrayList<>())
328							.build();
329					for (IndicatorEvent event : events) {
330						nodeDto.getChilds().add(NodeDto.builder()
331								.code(event.getCode())
332								.name(event.getEventName())
333								.categoryId(event.getCategoryId())
334								.categoryName(event.getCategoryName())
335								.childs(null)
336								.build());
337					}
338					res.add(nodeDto);
339				}
340				return res;
341			}
342			return res;
343		}
