352			DicRuleNodeExample example = new DicRuleNodeExample();
353			DicRuleNodeExample.Criteria criteria = example.createCriteria();
354	
355			if (BusinessVersion.VERSION2_0.getVersion().equals(param.getBusinessVersion())
356					|| OrderModeEnum.TWO_ZERO.getType().equals(param.getOrderMode())) {
