358						.andOrderModeEqualTo(OrderModeEnum.TWO_ZERO.getType())
359						.andDeliveryTypeEqualTo(param.getDeliveryType())
360						.andIsMeasurementNodeEqualTo(param.getHasMeasurementNode().equals(1))
361						.andIsDeliverynotificationNodeEqualTo(param.getHasDeliveryNotificationNode().equals(1));
362			} else {
363				criteria.andNodeTypeEqualTo(RuleNodeTypeEnum.ORDER_NODE.getType())
364						.andDeliveryTypeEqualTo(param.getDeliveryType())
365						.andOrderModeEqualTo(OrderModeEnum.TWO_FIVE.getType());
366			}
367			if (Objects.nonNull(param.getOrderType())
368					&& SecondType.REPLENISH_BEFORE_COMPLETION_DECORATE.getSecondType() != param.getOrderType()
369				&& SecondType.REPLENISH_BEFORE_COMPLETION_RETAIL.getSecondType() != param.getOrderType()) {
370				// 排除图纸上传
371				criteria.andCodeNotEqualTo(DispatchReceiveActionTypeEnum.COE_PLATFORM_UPLOAD_DRAWING.getCode().toString());
372			}
373			example.setOrderByClause("squence_num asc");
374			List<DicRuleNode> orderRuleNodes = dicRuleNodeMapper.selectByExample(example);
375			if (!CollectionUtils.isEmpty(orderRuleNodes)) {
376				nodeDto.setChilds(convertToNodeDto(orderRuleNodes));
377			}
378			return nodeDto;
