281	    public ScheduleDAG rebuild(Long version) throws RpcException {
282	        LOGGER.info("构建排程考核DAG, 版本: {}", version);
283	
284	        // 1.0 基础数据准备
285	        // 基础事件
286	        List<IndicatorBaseEvent> allBaseEvents = getAllBaseEvents();
287	
288	        // 材料排程考核规则
289	        List<ProcessNodeCfgDTO> processNodeCfgList = constructionScheduleService.getIndicatorRules(version);
290	        processNodeCfgList = processNodeCfgList.stream()
291	                .filter(cfg -> StringUtils.isNotEmpty(cfg.getMaterialCode()))
292	                .collect(Collectors.toList());
293	        LOGGER.info("scheduleRebuild基础数据准备完成");
294	
295	        // 2.0 将基础数据整理成DAG结构
296	        // 材料, 基装包映射
297	        // 材料可以出现在a -> b中的任意一端, 基装包只会出现在a端
298	        Map<String, String> categoryMap = new HashMap<>();
299	        categoryMap.putAll(processNodeCfgList.stream()
300	                .collect(Collectors.toMap(ProcessNodeCfgDTO::getMaterialCode, ProcessNodeCfgDTO::getMaterialName, (v1, v2) -> v1)));
301	        for (ProcessNodeCfgDTO cfg : processNodeCfgList) {
302	            for (NodeAssessmentRuleCfgDTO ruleCfg : cfg.getNodeAssessmentRuleCfgList()) {
303	                if (StringUtils.isNotEmpty(ruleCfg.getRelationMaterialCode())) {
304	                    categoryMap.put(ruleCfg.getRelationMaterialCode(), ruleCfg.getRelationMaterialName());
305	                }
306	            }
307	        }
308	
309	        // 排程code向ofcCode的映射， 不包含品类信息
310	        Map<String, String> uniqCodeToName = new HashMap<>();
311	        Map<String, String> scheduleCodeToCode = new HashMap<>();
312	
313	        // 初始化工期事件
314	        List<ScheduleEventNode> scheduleEventNodes = allBaseEvents.stream()
315	                .filter(event -> EventTypeEnum.CONSTRUCTION_SCHEDULE.getValue().equals(event.getEventType()))
316	                .map(event -> ScheduleEventNode.builder()
317	                        .uniqCode(event.getCode())
318	                        .name(event.getEventName())
319	                        .ofcCode(event.getCode())
320	                        .scheduleCode(event.getScheduleCode())
321	                        .categoryId("")
322	                        .categoryName("")
323	                        .eventType(event.getEventType())
324	                        .timeType(event.getTimeType())
325	                        .taskInfo(event.getTaskInfo())
326	                        .edgeInList(new ArrayList<>())
327	                        .edgeOutList(new ArrayList<>())
328	                        .build())
329	                .collect(Collectors.toList());
330	
331	        // 初始化品类事件(基装包事件也走此逻辑)
332	        for (String categoryId : categoryMap.keySet()) {
333	            String categoryName = categoryMap.get(categoryId);
334	            for (IndicatorBaseEvent event : allBaseEvents) {
335	                if (!EventTypeEnum.CONSTRUCTION_SCHEDULE.getValue().equals(event.getEventType())) {
336	                    ScheduleEventNode node = ScheduleEventNode.builder()
337	                            .uniqCode(categoryId + "_" + event.getCode())
338	                            .name(event.getEventName())
339	                            .ofcCode(event.getCode())
340	                            .scheduleCode(event.getScheduleCode())
341	                            .categoryId(categoryId)
342	                            .categoryName(categoryName)
343	                            .eventType(event.getEventType())
344	                            .timeType(event.getTimeType())
345	                            .taskInfo(event.getTaskInfo())
346	                            .edgeInList(new ArrayList<>())
347	                            .edgeOutList(new ArrayList<>())
348	                            .build();
349	                    scheduleEventNodes.add(node);
350	                    uniqCodeToName.put(node.getUniqCode(), node.getName());
351	                }
352	                scheduleCodeToCode.put(event.getScheduleCode(), event.getCode());
353	            }
354	        }
355	
356	        // {ruleId: {indexId: ScheduleEdgeRule, ...}}
357	        Map<String, Map<Integer, ScheduleEdgeRule>> scheduleEventRuleMap = new HashMap<>();
358	        for (ProcessNodeCfgDTO cfg : processNodeCfgList) {
359	            for (NodeAssessmentRuleCfgDTO ruleCfg : cfg.getNodeAssessmentRuleCfgList()) {
360	                String ruleId = getRuleId(cfg, ruleCfg);
361	                String codeFrom = convertNodeCode(ruleCfg.getRelationNodeCode(), ruleCfg.getRelationMaterialCode(), cfg.getTaskType(), scheduleCodeToCode);
362	                String codeTo = convertNodeCode(ruleCfg.getNodeCode(), ruleCfg.getMaterialCode(), cfg.getTaskType(), scheduleCodeToCode);
363	                if (!scheduleEventRuleMap.containsKey(ruleId)) {
364	                    scheduleEventRuleMap.put(ruleId, new HashMap<>());
365	                }
366	                if (!scheduleEventRuleMap.get(ruleId).containsKey(ruleCfg.getDivide())) {
367	                    boolean replenish = AssessRuleRestartTypeEnum.REBATE.getCode().equals(ruleCfg.getRestartType());
368	                    boolean restart = AssessRuleRestartTypeEnum.RESTART.getCode().equals(ruleCfg.getRestartType());
369	                    ScheduleEdgeRule edgeRule = ScheduleEdgeRule.builder()
370	                            .ruleId(ruleId)
371	                            .funcName(cfg.getValueRetrievalLogic().equals(0) || restart ? "最晚" : "最早")
372	                            .indexId(ruleCfg.getDivide())
373	                            .indicatorName(uniqCodeToName.get(codeTo))
374	                            .categoryId(cfg.getMaterialCode())
375	                            .categoryName(cfg.getMaterialName())
376	                            .deliveryId(cfg.getSupplierCode().equals("9999999") ? "-1" : cfg.getSupplierCode())
377	                            .deliveryType(cfg.getDeliveryType())
378	                            .restart(restart)
379	                            .replenish(replenish)
380	                            .codeFromList(new ArrayList<>())
381	                            .codeTo(codeTo)
382	                            .timeType(ruleCfg.getDurationType())
383	                            .timeRef(TIME_REF_MAP.getOrDefault(ruleCfg.getScheduleRelation(), ""))
384	                            .interval(new BigDecimal(ruleCfg.getDuration()))
385	                            .build();
386	                    scheduleEventRuleMap.get(ruleId).put(ruleCfg.getDivide(), edgeRule);
387	                }
388	                scheduleEventRuleMap.get(ruleId).get(ruleCfg.getDivide()).getCodeFromList().add(codeFrom);
389	            }
390	        }
391	
392	        // 将scheduleEventRuleMap完全打平
393	        List<ScheduleEdgeRule> scheduleEventRules = scheduleEventRuleMap.values()
394	                .stream()
395	                .flatMap(innerMap -> innerMap.values().stream())
396	                .collect(Collectors.toList());
397	
398	        LOGGER.info("scheduleRebuild数据拼装完成, eventNodes: {}, edgeRules: {}", scheduleEventNodes.size(), scheduleEventRules.size());
399	        ScheduleDAG res = ScheduleDAG.builder()
400	                .scheduleEventNodes(scheduleEventNodes)
401	                .scheduleEdgeRules(scheduleEventRules)
402	                .build();
403	        SCHEDULE_DAG_CACHE.put(version.toString(), JsonUtil.obj2JsonStr(res));
404	        return res;
405	    }
