407	    public String convertNodeCode(String nodeCode, String categoryId, String targetTaskType, Map<String, String> scheduleCodeToCode) {
408	        if (StringUtils.isEmpty(categoryId)) {
409	            // 工期类节点
410	            return scheduleCodeToCode.get(nodeCode);
411	        }
412	        String taskTypeStr = nodeCode.replace("_" + categoryId, "");
413	        if (taskTypeStr.equals("task_generate")) {
414	            // 生成类节点
415	            return categoryId + "_" + scheduleCodeToCode.get(targetTaskType) + "_generate";
416	        }
417	        if (taskTypeStr.startsWith("task_activate")) {
418	            // 激活类节点
419	            return categoryId + "_" + scheduleCodeToCode.get(targetTaskType) + "_active";
420	        }
421	        // 普通品类节点
422	        return categoryId + "_" + scheduleCodeToCode.get(taskTypeStr);
423	
424	    }
