437	    public List<ScheduleEventNode> getFigureNodeList(List<ScheduleEventNode> startNodes, ScheduleAllNode scheduleAllNode) {
438	        initOrderNode(scheduleAllNode);
439	        initDispatchNode(scheduleAllNode);
440	
441	        // startNodes 支持多个起始点
442	        List<ScheduleEventNode> res = new ArrayList<>();
443	        for (ScheduleEventNode startNode : startNodes) {
444	            Stack<String> circleVisited = new Stack<>();
445	            List<ScheduleEventNode> figureNodeList = new ArrayList<>();
446	            dfs(startNode, scheduleAllNode, circleVisited, figureNodeList);
447	            res.addAll(distinctNodes(figureNodeList));
448	        }
449	        return distinctNodes(res);
450	    }
