452	    public List<ScheduleEventNode> getDataNodeList(List<ScheduleEventNode> fugureNodeList, ScheduleAllNode scheduleAllNode) {
453	        // 获取全部需要拉取轨迹的node
454	        Set<ScheduleEventNode> dataNodeSet = new HashSet<>();
455	        for (ScheduleEventNode node : fugureNodeList) {
456	            ScheduleOrderDispatchNode scheduleOrderDispatchNode = getOrderDispatchNode(node, scheduleAllNode);
457	            for (ScheduleNodeEdge edge : node.getEdgeInList()) {
458	                // 只要有符合条件的载体, 就需要拉取数据
459	                if (hasFilterNode(edge.getRuleList(), scheduleOrderDispatchNode)) {
460	                    dataNodeSet.add(edge.getNodeFrom());
461	                    // 验证通过的话, figureNode自身也需要获取时间
462	                    // 因为实际完成时间需要写到考核结果中
463	                    dataNodeSet.add(node);
464	                }
465	            }
466	        }
467	        return new ArrayList<>(dataNodeSet);
468	    }
