470	    private ScheduleOrderDispatchNode getOrderDispatchNode(ScheduleEventNode node, ScheduleAllNode scheduleAllNode) {
471	        ScheduleOrderDispatchNode res = ScheduleOrderDispatchNode.builder()
472	                .orderNodes(new ArrayList<>())
473	                .dispatchNodes(new ArrayList<>())
474	                .build();
475	
476	        // 判断current下是否挂载了任务载体
477	        if (!EVENT_ENTITY.containsKey(node.getName())) {
478	            return res;
479	        }
480	        String categoryId = node.getCategoryId();
481	        List<Integer> entityInfo = EVENT_ENTITY.get(node.getName());
482	        Integer entityType = entityInfo.get(0);
483	        Integer taskType = entityInfo.get(1);
484	
485	        // 根据节点类型, 获取对应的载体列表
486	        if (ORDER_NODE.equals(entityType)) {
487	            res.setOrderNodes(scheduleAllNode.getOrderNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>()));
488	        }
489	        if (DISPATCH_NODE.equals(entityType)) {
490	            res.setDispatchNodes(scheduleAllNode.getDispatchNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>()));
491	        }
492	        return res;
493	    }
