816	    /**
817	     * 根据projectOrderId
818	     * constructionDiff: 是否计算工期差异
819	     * beforeContract: 是否将签前节点放入extNodes(未计算出考核结果的设计、测量、复尺、下单)
820	     * basicDiffList： 基装包差异节点列表
821	     */
822	    public FigureScheduleParam getBaseEventsBySchedule(String projectOrderId, Boolean constructionDiff, Boolean beforeContract, Set<String> basicNodeCodeSet) throws RpcException {
823	
824	        ScheduleDAG indicatorDAG = getScheduleDAG(projectOrderId);
825	        if (Objects.isNull(indicatorDAG) || CollectionUtils.isEmpty(indicatorDAG.getScheduleEventNodes())) {
826	            return null;
827	        }
828	
829	        List<ScheduleEventNode> eventNodeList = indicatorDAG.getScheduleEventNodes();
830	
831	        FigureScheduleParam res = FigureScheduleParam.builder()
832	                .projectOrderId(projectOrderId)
833	                .startNodes(new ArrayList<>())
834	                .extNodes(new ArrayList<>())
835	                .build();
836	
837	        // 需要计算工期差异的话, 将工期节点作为startNode
838	        if (constructionDiff) {
839	            res.getStartNodes().addAll(eventNodeList.stream()
840	                    .filter(eventNode -> eventNode.getEventType().equals(EventTypeEnum.CONSTRUCTION_SCHEDULE.getValue()))
841	                    .collect(Collectors.toList()));
842	        }
843	
844	        // 需要计算签前节点
845	        if (beforeContract) {
846	            Set<String>  extCodeSet = getNodesBeforeContract(projectOrderId);
847	            for (ScheduleEventNode en : eventNodeList) {
848	                if (extCodeSet.contains(en.getUniqCode())) {
849	                    res.getExtNodes().add(en);
850	                }
851	            }
852	        }
853	
854	        // 处理基装包差异节点
855	        if (CollectionUtils.isNotEmpty(basicNodeCodeSet)) {
856	            res.getStartNodes().addAll(eventNodeList.stream()
857	                    .filter(en -> en.getEventType().equals(EventTypeEnum.BASIC_PACKAGE_SCHEDULE.getValue()))
858	                    .filter(en -> basicNodeCodeSet.contains(String.format("%s_%s", en.getScheduleCode(), en.getCategoryId())))
859	                    .collect(Collectors.toList()));
860	        }
861	        return res;
862	    }
