902	        Map<String, String> constructionMap = tasks.stream()
903	                .filter(t -> EnumTransformUtil.CONSTRUCTION_ACTION_TYPE_SET.contains(t.getTaskType()))
904	                .collect(Collectors.toMap(
905	                        DeliveryProcessTaskDTO::getNodeCode,
906	                        t -> EvalScheduleOrderService.DEFAULT_TIME.equals(t.getFormTime()) ? t.getPredictStartTime() : t.getFormTime(),
907	                        (v1, v2) -> v1)
908	                );
909	        String value = String.format("%s_%s_%s_%s_%s_%s_%s_%s_%s",
910	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.START_DISCLOSURE.getSequenceCode()),
911	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.TECHNICAL_DISCLOSURE.getSequenceCode()),
912	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.HYDROELECTRIC_ACCEPTANCE.getSequenceCode()),
913	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.WOOD_ACCEPTANCE.getSequenceCode()),
914	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.BASE_COMPLETION_ACCEPTANCE.getSequenceCode()),
915	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.COMPLETION_ACCEPTANCE.getSequenceCode()),
916	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.SOFT_ACCEPTANCE.getSequenceCode()),
917	                constructionMap.get(EnumTransformUtil.FIRST_BATCH_MATERIAL_ACCEPTANCE),
918	                constructionMap.get(EnumTransformUtil.SECOND_BATCH_MATERIAL_ACCEPTANCE));
919	
920	        String key = "scm-workbench:schedule-construction-diff:" + projectOrderId;
921	
