75	    public IndicatorDAG getIndicatorDAG() {
76	        // 获取redis中的版本号, 如果没有则初始化为1
77	        RAtomicLong redisVersion = redissonClient.getAtomicLong(DAG_VERSION);
78	        if (redisVersion.get() == 0L) {
79	            redisVersion.incrementAndGet();
80	        }
81	        IndicatorDAG res;
82	        String cacheString = DAG_CACHE.getOrDefault(IndicatorDAGKey, null);
83	        // 当前事例版本号小于redis中版本号, 直接重新构建
84	        if (currentVersion.get() == 0 || currentVersion.get() < redisVersion.get()) {
85	            cacheString = null;
86	        }
87	        if (cacheString == null) {
88	            synchronized (lock) {
89	                long currentVer = currentVersion.get();
90	                long totalVer = redisVersion.get();
91	                if (currentVer == 0 || currentVer < totalVer) {
92	                    LOGGER.info("DAG缓存重新构建, 当前版本: {}, 远端版本: {}", currentVer, totalVer);
93	                    rebuild();
94	                    currentVersion.set(totalVer);
95	                }
96	            }
97	        }
98	
